package com.mockarena.evaluation;
import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.test.context.*; import org.springframework.test.web.servlet.MockMvc; import org.testcontainers.containers.PostgreSQLContainer; import org.testcontainers.junit.jupiter.*; import java.util.*; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest(properties="evaluation.preparation.enabled=false") @AutoConfigureMockMvc @Testcontainers class EvaluationWorkloadSecurityIntegrationTest {
 @Container static final PostgreSQLContainer<?> postgres=new PostgreSQLContainer<>("postgres:16-alpine");
 @DynamicPropertySource static void props(DynamicPropertyRegistry r){r.add("spring.datasource.url",postgres::getJdbcUrl);r.add("spring.datasource.username",postgres::getUsername);r.add("spring.datasource.password",postgres::getPassword);r.add("evaluation.workload-auth.incoming-token",()->"evaluation-test-token");r.add("evaluation.workload-auth.assessment-snapshot-token",()->"assessment-test-token");r.add("evaluation.workload-auth.question-coding-token",()->"question-test-token");}
 @Autowired MockMvc mvc;
 @Test void internalJobAcceptanceRequiresWorkloadIdentity() throws Exception {String body="{\"attemptId\":\""+UUID.randomUUID()+"\",\"globalPosition\":1,\"questionId\":\""+UUID.randomUUID()+"\",\"questionVersionId\":\""+UUID.randomUUID()+"\",\"submittedResponseFingerprint\":\""+"a".repeat(64)+"\",\"programmingLanguage\":\"JAVA\"}";mvc.perform(post("/internal/v1/coding-evaluation-jobs").contentType("application/json").content(body)).andExpect(status().isUnauthorized());mvc.perform(post("/internal/v1/coding-evaluation-jobs").header("X-MockArena-Workload-Token","evaluation-test-token").contentType("application/json").content(body)).andExpect(status().isOk()).andExpect(jsonPath("$.status").value("RECEIVED"));}
}
